study_image::ImageStore images(gl);
    const auto menu_icon=images.load(std::filesystem::u8path(image_path));
    const auto play_pixels=study_texture::make_play_badge();
    const auto play_icon=images.create({play_pixels.data(),play_pixels.size(),8,8});
    if(!menu_icon || !play_icon) {
        std::fprintf(stderr,"Image load/upload/registration failed\n");
        return 1;
    }
    study_texture::Quad badge_quad(gl);
    if (!badge_quad.init()) return 1;

void image_unload(ImageHandle handle)
{
    const ImageEntry* entry=s_images.find(handle);
    if(!entry) return;
    if(entry->tex) {
        glb_before_texture_delete(entry->tex);
        gl_DeleteTextures(1,&entry->tex);
    }
    s_images.erase(handle);
}
